-- ────────────────────────────────────────────────────────────────────────────
-- Seed: First 150 bestiary monsters (the ones with images).
-- Idempotent: wipes all monsters + dependent gameplay rows, reseeds 1..150.
-- Re-run after every art-batch threshold (200, 250, 300, ...) with the
-- bestiary_id range bumped accordingly.
-- ────────────────────────────────────────────────────────────────────────────

BEGIN;

-- 1. Clear gameplay rows that FK into monsters (preserve banners, profiles, tasks)
DELETE FROM public.user_monsters;
DELETE FROM public.pulls;
DELETE FROM public.fusion_recipes;
UPDATE public.banners SET featured_monster_id = NULL;

-- 2. Wipe monsters
DELETE FROM public.monsters;

-- 3. Insert first 150 monsters

COMMIT;
